// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        address caller = address(0x1234);
        vm.deal(caller, 100 ether);

        vm.warp(1000);
        vm.roll(1);
        vm.prank(caller);
        (bool success1,) = address(c).call{value: 10 ether}("");
        assertTrue(success1);

        vm.warp(2000);
        vm.roll(2);
        vm.prank(caller);
        (bool success2,) = address(c).call{value: 10 ether}("");
        assertTrue(success2);

        vm.warp(3000);
        vm.roll(15);
        vm.prank(caller);
        (bool success3,) = address(c).call{value: 10 ether}("");
        assertTrue(success3);

        vm.warp(3000);
        vm.roll(16);
        vm.prank(caller);
        bool ok4;
        (bool success4,) = address(c).call{value: 10 ether}("");
        ok4 = success4;

        assertFalse(ok4);
    }
}
